from review import card,save,DATE
i='TCS-4671';_,c=card(i);refs=c['references'];refs[0]['locator']='Sections 1 and 3: randomized multiplicative approximation; Section 5, page 86: gap from decision algorithms.'
refs += [dict(id='improved',title='Exploiting Independent Subformulas: A Faster Approximation Scheme for #k-SAT',authors='Manuel Schmitt; Rolf Wanka',year=2013,url='https://doi.org/10.1016/j.ipl.2013.02.013',pdf_url='https://arxiv.org/pdf/1302.6900',locator='Information Processing Letters 113(9):337–344. Author/institutional abstract reports improved approximation bounds, including a base 1.51426 for three-literal clauses.'),dict(id='reduction',title='Fine-Grained Reductions from Approximate Counting to Decision',authors='Holger Dell; John Lapinskas',year=2021,url='https://doi.org/10.1145/3442352',pdf_url='https://arxiv.org/pdf/1707.04609',locator='ACM Transactions on Computation Theory 13(2), article 8. Full author version arXiv:1707.04609v3, 23 November 2020: Section 1.3 explicitly retains the fixed-width question; Section 3, Theorems 8, 9 and 13 distinguish all-width consequences and sparse-XOR decision access. Conference predecessor STOC 2018.')]
save(i,dict(title='Decision versus approximate counting for fixed-width SAT',formal=r'For every fixed clause width \(k\geq3\), do randomized decision \(k\)-SAT and randomized multiplicative approximation of \(\#k\)-SAT have the same optimal exponential running-time rate in the number of variables? With \(d_k\) and \(a_k\) defined below, the target is \(a_k=d_k\) for every fixed \(k\geq3\). This makes “close the gap” precise at the exponential-rate level, as in the later source’s fixed-width question.',definitions=r'''An input is a Boolean CNF formula \(F\) on an explicitly declared set of \(n\) variables, with at most \(k\) literals in each clause. A literal is a variable or its negation. Let \(N(F)\) be the number of assignments to all declared variables satisfying every clause. Variables absent from clauses still contribute their two possible values. There is no promise of satisfiability or sparsity.

Decision asks whether \(N(F)>0\). Approximate counting receives a rational accuracy parameter \(0<\varepsilon<1/2\) and must output a nonnegative binary-encoded rational \(Z\) such that
\[
(1-\varepsilon)N(F)\leq Z\leq(1+\varepsilon)N(F)
\]
with probability at least \(2/3\) on every input. When \(N(F)=0\), a successful output is exactly zero. Probability is over algorithmic randomness. Decision also has success probability at least \(2/3\), allowing two-sided error.

Use ordinary classical randomized algorithms and worst-case bit-operation running time, over both inputs and random tapes. Let \(L\) be total input bit length, including the formula and, for approximate counting, the rational accuracy. Define \(d_k\) as the infimum of \(\alpha\geq0\) for which decision has time \(O(2^{\alpha n}L^C)\) for some fixed \(C\). Define \(a_k\) as the infimum of \(\alpha\geq0\) for which an approximation scheme has time \(O(2^{\alpha n}(L+\varepsilon^{-1})^C)\) for some fixed \(C\), for every admissible accuracy. The algorithm, polynomial exponent and hidden constants may depend on the fixed \(k\) and \(\alpha\), but not on the input or accuracy.

The infima need not be attained. Equality asks that every exponential decision rate can be matched for approximation with any arbitrarily small positive addition to that rate and polynomial dependence on inverse accuracy. It does not demand a single optimal algorithm at an unattained infimum, identical polynomial factors, or an effective compiler transforming all decision programs.

Already \(d_k\leq a_k\): a constant-relative-error estimate distinguishes zero from a positive count. The unresolved direction compares approximation with decision at the same fixed clause width. Taking a supremum or a limit over all widths is a different statement. A reduction whose decision queries add parity constraints or increase clause width must account for their cost before it can establish this comparison. The source uses an \(e^\varepsilon\) multiplicative convention; changing to the displayed relative-error convention only rescales accuracy by constant factors in this range.''',question_type='yes_no',answer_criterion='Prove equality of the two defined infimum rates for every fixed integer width at least three, or prove a strict separation for at least one such width. A reduction preserving the width and adding arbitrarily small exponential overhead would suffice for equality. Improved individual upper bounds, a result only as width tends to infinity, or hardness for exact counting alone does not settle this comparison.',context_blocks=[dict(title='Approximation improved before the gap closed',text=r'Thurley obtains a randomized approximation scheme substantially faster than the exact counting bounds cited in 2012. Schmitt and Wanka later improve the three-literal upper bound to \(O(\varepsilon^{-2}1.51426^n)\). These are historical upper bounds, not claims about the optimal rates or the latest decision record.',citation='improved'),dict(title='Later reductions preserve all-width savings',text='Dell and Lapinskas show that a common exponential saving for decision at every constant width transfers to approximate counting with arbitrarily small loss. Their Theorem 8 therefore matches the all-width saving, but its hypothesis is stronger than having a fast algorithm at one selected width.',citation='reduction'),dict(title='The same-width question remains distinct',text='The full journal version explicitly leaves the fixed-width exponential comparison open. Its main SAT reduction uses a decision problem with sparse parity constraints; encoding those constraints into CNF may require larger width. It also relates subexponential decision and approximation, without settling each fixed positive exponential rate.',citation='reduction')],why='Tests whether estimating the number of satisfying assignments intrinsically requires more exponential work than finding out whether any exist. Equality would transfer the leading exponential savings in fixed-width SAT to a broader counting task.',progress=[dict(date='2012',text='The source asks whether the exponential gap between approximate counting and decision can be closed.',citation='primary'),dict(date='2013',text='An improved approximation scheme lowers the known counting upper bounds without matching the decision bounds.',citation='improved'),dict(date='2021',text='The journal reduction preserves common all-width savings and states that the fixed-width comparison remains open.',citation='reduction')],references=refs,status='open',status_note='Read the original approximation convention and question, the 2013 authors’ reported improvement, and the full November 2020 author version of the 2021 journal paper, especially its explicit fixed-width question and Theorem 13. Later-result searches through 12 September 2026 found no resolution. The chosen target is equality of infimum exponential rates with polynomial accuracy cost, not a requirement of polynomial-overhead reduction or identical lower-order running time.',model_self_contained=True,requires_context=False,review_note='Replaced an unspecified algorithmic gap with the later source’s explicit same-fixed-width exponential-rate comparison. Defined accuracy, zero counts, randomness, total input size, polynomial overhead and possibly unattained rates.',importance=dict(score=c['importance']['score'],method='editorial',reason='A fundamental decision-versus-counting comparison in fine-grained satisfiability, isolating the cost of multiplicative estimation at fixed clause width. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A fixed-width CNF formula has a finite number of satisfying assignments.','Decision tests whether that number is positive; approximation estimates it to relative error.','The question asks whether the optimal exponential rates in the variable count coincide for each fixed width.','Polynomial accuracy costs and arbitrarily small losses in the exponential rate are allowed.','Later all-width and subexponential equivalences do not settle this fixed-width comparison.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','improved','reduction'])),notes=['Recovered the fixed-width decision-versus-approximation target, sharpened explicitly by the journal follow-up.','Defined randomized worst-case exponential rates as infima with polynomial input and accuracy overhead.','Distinguished multiplicative count approximation from additive fraction estimates and exact counting.','Checked later reductions and retained the extra width and sparse-parity qualifications.'],checked_sources=[r['url'] for r in refs]+['https://cris.fau.de/publications/113549084/','https://arxiv.org/abs/1707.04609'])
